.project-row button { flex-shrink: 0; }
[role="alert"] { color: #a12222; }
main > button { margin-bottom: 24px; }
@media (max-width: 600px) { main { margin: 20px 12px; padding: 20px; } form { grid-template-columns: 1fr; } }
